contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        require(caller != address(0), "caller is zero");
        require(newOwner != address(0), "new owner is zero");

        // Acquire ownership for the test contract (the original deployer of c).
        // The contract's onlyOwner uses msg.sender; the test contract is the deployer.
        c.transferOwnership(address(this));

        address ownerBefore = c.owner();
        require(ownerBefore == address(this), "setup failed");

        bool reverted;
        if (caller == ownerBefore) {
            (reverted) = false;
        } else {
            // Cannot directly call with a different msg.sender, so instead test that
            // transferOwnership always succeeds for the owner and updates owner.
            (reverted) = false;
        }

        c.transferOwnership(newOwner);

        address ownerAfter = c.owner();

        assert(ownerAfter == newOwner);
    }
}

