    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        address initialOwner = c.owner();

        bool callerIsOwner = (caller == initialOwner);
        bool success;

        if (callerIsOwner) {
            c.transferOwnership(newOwner);
            success = true;
        } else {
            bool reverted;
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            success = !reverted;
